function wispBeamLength(center,angle){let last=0;for(let distance=10;distance<=500;distance+=10){let target={x:center.x+Math.cos(angle)*distance,y:center.y+Math.sin(angle)*distance};if(!lineClear(center,target)){let low=last,high=distance;for(let i=0;i<8;i++){let mid=(low+high)/2;if(lineClear(center,{x:center.x+Math.cos(angle)*mid,y:center.y+Math.sin(angle)*mid}))low=mid;else high=mid;}return low;}last=distance;}return last;}
function beginWispBeams(e){let angle=Math.atan2(p.y-e.y,p.x-e.x),center={x:e.x,y:e.y};e.state='attack';e.elapsed=0;e.struck=false;e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;e.attack={pattern:'wispBeams',bespoke:true,center,angle,windup:1.35,halfWidth:18,offsets:[-.3,.3,0],impacts:[false,false,false]};e.attack.lengths=e.attack.offsets.map(offset=>wispBeamLength(center,angle+offset));}
function wispBeamContains(a,point,index){let angle=a.angle+a.offsets[index],dx=point.x-a.center.x,dy=point.y-a.center.y,along=dx*Math.cos(angle)+dy*Math.sin(angle),across=-dx*Math.sin(angle)+dy*Math.cos(angle);return a.lengths[index]>0&&along>=0&&along<=a.lengths[index]&&Math.abs(across)<=a.halfWidth;}
const wispAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r1e3')return wispAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0)return;
 if(e.state!=='attack'&&e.t<=dt&&dist(e,p)<=500&&lineClear(e,p))beginWispBeams(e);
 let a=e.attack;if(a?.pattern!=='wispBeams')return wispAnimateBase(e,dt);e.elapsed+=dt;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);
 for(let i=0;i<3;i++)if(e.elapsed>=a.windup+i*.35&&!a.impacts[i]){a.impacts[i]=true;if(wispBeamContains(a,p,i)&&lineClear(a.center,p))hurt(36);if(typeof playSound==='function')playSound('arc',e.x,e.y);}
 e.struck=a.impacts[2];if(e.elapsed>=a.windup+.7+1){e.attack=null;e.state='idle';e.t=1.2;}
};
const wispSheet=new Image();wispSheet.assetSrc='assets/cave-wisp-anim.png';
const wispDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{
 if(e.species!=='r1e3')return wispDrawBase(e,size);let pos=project(e.x,e.y),a=e.attack,frame=spriteFrame(e.state,e.anim),lift=e.hp>0?8+Math.sin(e.anim*3)*3:0;
 if(a?.pattern==='wispBeams')frame={row:2,col:e.elapsed<.6?0:e.elapsed<a.windup?1:e.elapsed<a.windup+.9?2:3};
 ctx.save();ctx.translate(pos.x,pos.y);ctx.scale(e.facing||1,1);ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(0,0,20,7,0,0,Math.PI*2);ctx.fill();if(wispSheet.complete&&wispSheet.naturalWidth){let sw=wispSheet.naturalWidth/4,sh=wispSheet.naturalHeight/3,w=150,h=w*sh/sw;ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,wispSheet,frame.col*sw,frame.row*sh,sw,sh,-w/2,-h*.86-lift,w,h);else ctx.drawImage(wispSheet,frame.col*sw,frame.row*sh,sw,sh,-w/2,-h*.86-lift,w,h);}ctx.restore();return true;
};
const wispGroundBase=drawGroundEffects;drawGroundEffects=()=>{wispGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r1e3'):enemies)){let a=e.attack;if(e.species!=='r1e3'||e.hp<=0||a?.pattern!=='wispBeams'||!visibleAt(e.x,e.y))continue;ctx.save();for(let i=0;i<3;i++){let until=a.windup+i*.35-e.elapsed;if(until<=0||a.lengths[i]<=0)continue;ctx.strokeStyle='#a4eaf1';ctx.fillStyle='#76d9ef20';ctx.lineWidth=1.5;ctx.globalAlpha=.4+.6*clamp(1-until/1.5,0,1);finalPolygon({center:a.center,angle:a.angle+a.offsets[i]},[[0,-a.halfWidth],[a.lengths[i],-a.halfWidth],[a.lengths[i],a.halfWidth],[0,a.halfWidth]]);}ctx.restore();}};
const wispEffectsBase=drawEffects;drawEffects=()=>{wispEffectsBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r1e3'):enemies)){let a=e.attack;if(e.species!=='r1e3'||e.hp<=0||a?.pattern!=='wispBeams'||!visibleAt(e.x,e.y))continue;ctx.save();for(let i=0;i<3;i++){let age=e.elapsed-a.windup-i*.35;if(age<0||age>.2||a.lengths[i]<=0)continue;let angle=a.angle+a.offsets[i],from=project(a.center.x,a.center.y),to=project(a.center.x+Math.cos(angle)*a.lengths[i],a.center.y+Math.sin(angle)*a.lengths[i]);ctx.globalAlpha=1-age/.2;ctx.lineCap='round';for(let [width,color]of [[14,'#79dbe580'],[5,'#d0fbff'],[2,'#ffffff']]){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(from.x,from.y-12);ctx.lineTo(to.x,to.y-12);ctx.stroke();}}ctx.restore();}};

